"""Load config/defaults.toml, then config/local.toml, then APP_ variables."""

from __future__ import annotations

import os
import tomllib
from pathlib import Path

from confload.merge import deep_merge

ENV_PREFIX = "APP_"


def read_toml(path: Path) -> dict:
    """Parse a TOML file; a missing file counts as an empty table."""
    if not path.is_file():
        return {}
    with path.open("rb") as handle:
        return tomllib.load(handle)


def env_overrides(environ: dict[str, str]) -> dict:
    """APP_SERVER__PORT=9000 becomes {"server": {"port": "9000"}}."""
    result: dict = {}
    for name, value in environ.items():
        if not name.startswith(ENV_PREFIX):
            continue
        keys = name[len(ENV_PREFIX) :].lower().split("__")
        node = result
        for key in keys[:-1]:
            node = node.setdefault(key, {})
        node[keys[-1]] = value
    return result


def load(root: str = ".", environ: dict[str, str] | None = None) -> dict:
    """Merge the defaults, the optional local file, and environment overrides."""
    config_dir = Path(root) / "config"
    config = read_toml(config_dir / "defaults.toml")
    config = deep_merge(config, read_toml(config_dir / "local.toml"))
    env = os.environ if environ is None else environ
    return deep_merge(config, env_overrides(dict(env)))

