from confload.loader import env_overrides, load
from confload.merge import deep_merge


def test_defaults():
    config = load(environ={})
    assert config["server"]["port"] == 8080
    assert config["logging"]["level"] == "info"


def test_env_override():
    config = load(environ={"APP_SERVER__PORT": "9000"})
    assert config["server"]["port"] == "9000"
    assert config["server"]["host"] == "127.0.0.1"


def test_deep_merge():
    assert deep_merge({"a": {"b": 1, "c": 2}}, {"a": {"c": 3}}) == {"a": {"b": 1, "c": 3}}


def test_env_overrides_ignores_other_variables():
    assert env_overrides({"HOME": "/tmp", "APP_DEBUG": "1"}) == {"debug": "1"}

