"""Write a config dict as TOML (tables of strings, numbers, and booleans)."""

from __future__ import annotations

import json
from pathlib import Path


def toml_value(value: object) -> str:
    """TOML text for a scalar value."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    return json.dumps(str(value))


def dumps(config: dict) -> str:
    """Top-level scalars first, then one [table] per nested dict."""
    lines = [f"{k} = {toml_value(v)}" for k, v in config.items() if not isinstance(v, dict)]
    for key, table in config.items():
        if isinstance(table, dict):
            lines += ["", f"[{key}]"]
            lines += [f"{k} = {toml_value(v)}" for k, v in table.items()]
    return "\n".join(lines).lstrip("\n") + "\n"


def save(config: dict, path: str) -> None:
    """Write config to path as TOML."""
    Path(path).write_text(dumps(config), encoding="utf-8")

